package com.m3.collections;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import java.util.Random;
import java.util.concurrent.atomic.AtomicInteger;

/** Independent JDK List oracle for mask-first sorting over primitive physical offsets. */
public final class M3PhysicalStateSnapshotProof {
    private static final Comparator<Integer> ORDER =
            Comparator.nullsFirst(Comparator.naturalOrder());
    private static long assertions;

    private M3PhysicalStateSnapshotProof() { }

    private static void check(boolean condition, String why) {
        assertions++;
        if (!condition) throw new AssertionError(why + " check=" + assertions);
    }

    private static void equal(Object expected, Object actual, String why) {
        assertions++;
        if (!Objects.equals(expected, actual)) {
            throw new AssertionError(why + " expected=" + expected + " actual=" + actual);
        }
    }

    private static void rejected(Class<? extends Throwable> expected, Runnable action, String why) {
        assertions++;
        try {
            action.run();
            throw new AssertionError(why + ": expected " + expected.getSimpleName());
        } catch (Throwable caught) {
            if (!expected.isInstance(caught)) {
                throw new AssertionError(why + ": unexpected " + caught, caught);
            }
        }
    }

    private static void scenario(Integer[] input, Random random,
            int required, int forbidden, M3IndexPathMasks.Backend backend) {
        M3IndexedListSnapshot<Integer> base = M3IndexedListSnapshot.copyOf(input);
        int from = random.nextInt(input.length + 1);
        int length = random.nextInt(input.length - from + 1);
        M3IndexedListSnapshot<Integer> view = base.slice(from, length);
        if (random.nextBoolean()) view = view.sorted(ORDER);
        if (random.nextBoolean()) view = view.sorted(ORDER.reversed());
        int[] states = new int[input.length];
        for (int i = 0; i < states.length; i++) states[i] = random.nextInt();
        int[] originalStates = states.clone();
        List<Integer> expectedSlots = new ArrayList<>();
        List<Integer> expectedValues = new ArrayList<>();
        for (int i = 0; i < view.size(); i++) {
            int slot = view.physicalIndex(i);
            int word = states[slot];
            if ((word & required) == required && (word & forbidden) == 0) {
                expectedSlots.add(slot);
                expectedValues.add(input[slot]);
            }
        }
        Object[] preimage = view.toArray();
        M3IndexedListSnapshot<Integer> selected =
                view.maskedByPhysicalState(states, required, forbidden, backend);
        M3IndexedListSnapshot<Integer> sorted =
                view.sortedMaskedByPhysicalState(states, required, forbidden, ORDER, backend);
        equal(expectedValues, selected, "selected values retain occurrence order");
        equal(expectedSlots.size(), selected.size(), "selected cardinality");
        for (int i = 0; i < selected.size(); i++) {
            equal(expectedSlots.get(i), selected.physicalIndex(i), "selected physical slot");
        }
        List<Integer> sortedSlots = new ArrayList<>(expectedSlots);
        sortedSlots.sort((left, right) -> ORDER.compare(input[left], input[right]));
        List<Integer> sortedValues = new ArrayList<>();
        for (int slot : sortedSlots) sortedValues.add(input[slot]);
        equal(sortedValues, sorted, "sorted mask-first values");
        for (int i = 0; i < sorted.size(); i++) {
            equal(sortedSlots.get(i), sorted.physicalIndex(i), "stable sorted physical slot");
        }
        check(Arrays.equals(preimage, view.toArray()), "source index view remains immutable");
        check(Arrays.equals(originalStates, states), "state lane is borrowed read-only");

        Arrays.fill(states, Integer.MIN_VALUE);
        equal(expectedValues, selected, "selection does not retain caller state");
        equal(sortedValues, sorted, "sorted selection does not retain caller state");
        for (int slot : expectedSlots) check(selected.includesPhysicalIndex(slot), "physical membership");
        rejected(UnsupportedOperationException.class, selected::clear, "immutable clear");
        rejected(UnsupportedOperationException.class,
                () -> selected.addAll(List.of()), "immutable no-op addAll");
    }

    private static void boundaries() {
        M3IndexedListSnapshot<Integer> source =
                M3IndexedListSnapshot.copyOf(new Integer[] {null, 7, 7, -5, null});
        int[] states = {Integer.MIN_VALUE, 1, 1, -1, 0};
        rejected(NullPointerException.class,
                () -> source.maskedByPhysicalState(null, 0, 0, M3IndexPathMasks.Backend.JAVA),
                "null physical lane");
        rejected(NullPointerException.class,
                () -> source.maskedByPhysicalState(states, 0, 0, null), "null backend");
        rejected(IllegalArgumentException.class,
                () -> source.maskedByPhysicalState(new int[4], 0, 0, M3IndexPathMasks.Backend.JAVA),
                "unequal physical state capacity");
        equal(List.of(), source.maskedByPhysicalState(states, 1, 1,
                M3IndexPathMasks.Backend.JAVA), "contradictory masks reject");
        M3IndexedListSnapshot<Integer> selected = source.maskedByPhysicalState(
                states, Integer.MIN_VALUE, 0, M3IndexPathMasks.Backend.JAVA);
        equal(Arrays.asList(null, -5), selected, "sign bit selection");
        check(selected.physicalIndex(0) == 0, "sign mask physical slots");
        check(selected.physicalIndex(1) == 3, "sign mask must retain encounter order");
    }

    private static void nativeRefusal() {
        if (M3IndexPathMasks.nativeAvailable()) return;
        M3IndexedListSnapshot<Integer> source =
                M3IndexedListSnapshot.copyOf(new Integer[] {1, 2, 3});
        AtomicInteger calls = new AtomicInteger();
        rejected(UnsatisfiedLinkError.class,
                () -> source.sortedMaskedByPhysicalState(
                        new int[] {1, 1, 1}, 1, 0, (a, b) -> {
                            calls.incrementAndGet();
                            return Integer.compare(a, b);
                        }, M3IndexPathMasks.Backend.NATIVE_REQUIRED),
                "native must refuse rather than fall back");
        equal(0, calls.get(), "no comparator callback before JNI refusal");
    }

    public static void main(String[] args) {
        boolean nativeRequired = args.length == 1 && "--native".equals(args[0]);
        if (nativeRequired && !M3IndexPathMasks.nativeAvailable()) {
            throw new AssertionError("requested M3 pathmask JNI is unavailable");
        }
        boundaries();
        nativeRefusal();
        M3IndexPathMasks.Backend backend = nativeRequired
                ? M3IndexPathMasks.Backend.NATIVE_REQUIRED : M3IndexPathMasks.Backend.JAVA;
        Random random = new Random(0x4d334d41534b3231L);
        Integer[][] seeds = {
            {}, {null}, {0}, {null, 7, 7, -5, null}, {3, 3, 2, 2, 1, 1}
        };
        for (Integer[] input : seeds) {
            scenario(input, random, 0, 0, backend);
            scenario(input, random, Integer.MIN_VALUE, 0, backend);
        }
        for (int iteration = 0; iteration < 1200; iteration++) {
            Integer[] input = new Integer[random.nextInt(100)];
            for (int i = 0; i < input.length; i++) {
                input[i] = random.nextInt(9) == 0 ? null : random.nextInt(15) - 7;
            }
            int required = random.nextBoolean() ? 1 << random.nextInt(32) : random.nextInt();
            int forbidden = random.nextBoolean() ? 1 << random.nextInt(32) : random.nextInt();
            scenario(input, random, required, forbidden, backend);
        }
        System.out.println("PASS M3PhysicalStateSnapshotProof assertions=" + assertions
                + " backend=" + backend);
    }
}
